:host { display: block; }
* { box-sizing: border-box; }
.studio {
  --bg0: #07090d; --bg1: #121822; --line: rgba(255,255,255,0.09); --text: #eef2f7; --muted: #8d99aa;
  --blue: #1c69d4; --blue2: #4d9bff; --should: #7fb2f0; --could: #6b7686; --warn: #f0b429;
  font-family: "Inter", "Helvetica Neue", Arial, sans-serif; color: var(--text);
  display: grid; grid-template-columns: minmax(0, 1fr) 380px; height: 680px; border-radius: 14px; overflow: hidden;
  background: radial-gradient(120% 90% at 35% 30%, #1d2734 0%, var(--bg1) 45%, var(--bg0) 100%);
  border: 1px solid #1f2733; container-type: inline-size;
}
@container (max-width: 860px) { .studio { grid-template-columns: 1fr; height: auto; } .stage { height: 460px; } .panel { max-height: 520px; } }

/* ---------------------------------------------------------------- stage */
.stage { position: relative; overflow: hidden; min-height: 0; }
.stage iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; opacity: 0; transition: opacity .8s ease; }
.stage.ready iframe { opacity: 1; }
.loader { position: absolute; inset: 0; display: grid; place-items: center; color: var(--muted); font-size: 13px; letter-spacing: .08em; text-transform: uppercase; }
.loader .bar { width: 160px; height: 2px; background: var(--line); margin-top: 12px; overflow: hidden; border-radius: 2px; }
.loader .bar i { display: block; height: 100%; width: 40%; background: var(--blue2); animation: slide 1.2s ease-in-out infinite; }
@keyframes slide { 0% { transform: translateX(-100%); } 100% { transform: translateX(260%); } }
.stage.ready .loader { display: none; }
.hud { position: absolute; left: 22px; top: 18px; right: 22px; display: flex; justify-content: space-between; align-items: flex-start; pointer-events: none; z-index: 3; }
.hud h2 { margin: 0; font-size: 26px; font-weight: 600; letter-spacing: -0.01em; color: #fff; }
.hud .sub { color: var(--muted); font-size: 13px; margin-top: 3px; }
.hud .sub b { color: var(--text); font-weight: 600; }
.hud .tools { display: flex; gap: 8px; pointer-events: auto; }
.btn { background: rgba(255,255,255,0.06); border: 1px solid var(--line); color: var(--text); border-radius: 999px;
  padding: 6px 13px; font-size: 12px; font-weight: 500; cursor: pointer; text-decoration: none; display: inline-flex; gap: 6px; align-items: center;
  backdrop-filter: blur(8px); transition: background .2s, border-color .2s; font-family: inherit; }
.btn:hover { background: rgba(255,255,255,0.12); border-color: rgba(255,255,255,0.2); }
.btn.on { background: var(--blue); border-color: var(--blue); }
.btn.primary { background: var(--blue); border-color: var(--blue); color: #fff; }
.btn.primary:hover { background: #2b7ae6; }

.pins { position: absolute; inset: 0; pointer-events: none; z-index: 2; }
.pin { position: absolute; transform: translate(-50%, -50%); pointer-events: auto; cursor: pointer; transition: opacity .25s; }
.pin .dot { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 700;
  color: #fff; background: var(--could); border: 2px solid rgba(255,255,255,0.85); box-shadow: 0 4px 18px rgba(0,0,0,.5); position: relative; }
.pin.Must .dot { background: var(--blue); }
.pin.Should .dot { background: #3a7fd0; }
.pin .dot::after { content: ""; position: absolute; inset: -7px; border-radius: 50%; border: 2px solid currentColor; opacity: 0; color: var(--blue2); }
.pin.Must .dot::after { animation: pulse 2.2s ease-out infinite; }
@keyframes pulse { 0% { transform: scale(.7); opacity: .8; } 100% { transform: scale(1.5); opacity: 0; } }
.pin .tag { position: absolute; left: 38px; top: 50%; transform: translateY(-50%); white-space: nowrap; font-size: 12px; font-weight: 500;
  background: rgba(10,14,20,0.82); border: 1px solid var(--line); padding: 4px 10px; border-radius: 6px; opacity: 0; transition: opacity .2s; pointer-events: none; }
.pin:hover .tag, .pin.sel .tag { opacity: 1; }
.pin.sel .dot { transform: scale(1.18); border-color: #fff; box-shadow: 0 0 0 4px rgba(77,155,255,.35), 0 4px 18px rgba(0,0,0,.5); }
.pin.back { opacity: .32; }
.pin.dim { opacity: .18; }

.rail { position: absolute; left: 0; right: 0; bottom: 0; padding: 14px 18px 16px; display: flex; gap: 8px; overflow-x: auto; z-index: 3;
  background: linear-gradient(transparent, rgba(5,7,10,.75)); scrollbar-width: none; }
.rail::-webkit-scrollbar { display: none; }
.rail .btn { flex: none; }
.rail .btn .n { background: rgba(255,255,255,.14); border-radius: 999px; padding: 0 6px; font-size: 11px; }
.credit { position: absolute; right: 16px; bottom: 58px; font-size: 10.5px; color: rgba(255,255,255,.42); z-index: 3; text-align: right; }
.credit a { color: inherit; }

/* ---------------------------------------------------------------- panel */
.panel { border-left: 1px solid var(--line); background: rgba(8,11,16,0.72); backdrop-filter: blur(14px); display: flex; flex-direction: column; min-height: 0; }
.panel .head { padding: 18px 20px 12px; border-bottom: 1px solid var(--line); }
.panel .eyebrow { font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }
.panel .title { font-size: 17px; font-weight: 600; margin-top: 4px; display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.panel .body { overflow-y: auto; padding: 8px 12px 18px; flex: 1; scrollbar-width: thin; scrollbar-color: #2a3442 transparent; }
.group { margin: 10px 0 4px; }
.group .gh { font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); padding: 6px 8px; cursor: pointer; display: flex; justify-content: space-between; }
.group .gh:hover { color: var(--text); }
.item { padding: 10px; border-radius: 10px; cursor: pointer; display: grid; grid-template-columns: 10px 1fr auto; gap: 10px; align-items: start; transition: background .15s; }
.item:hover { background: rgba(255,255,255,0.05); }
.item.sel { background: rgba(28,105,212,0.18); }
.item .pd { width: 8px; height: 8px; border-radius: 50%; margin-top: 6px; background: var(--could); }
.item .pd.Must { background: var(--blue2); } .item .pd.Should { background: var(--should); }
.item .t { font-size: 13.5px; line-height: 1.35; }
.item .m { font-size: 11.5px; color: var(--muted); margin-top: 3px; }
.item .sc { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; text-align: right; }
.item .bar { height: 3px; width: 46px; background: rgba(255,255,255,.08); border-radius: 2px; margin-top: 5px; }
.item .bar i { display: block; height: 100%; border-radius: 2px; background: var(--blue2); }
.empty { color: var(--muted); font-size: 13px; padding: 24px 8px; }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0 2px; }
.chip { font-size: 11px; font-weight: 600; padding: 2px 9px; border-radius: 999px; background: rgba(255,255,255,.08); color: var(--text); white-space: nowrap; }
.chip.Must { background: var(--blue); color: #fff; } .chip.Should { background: rgba(127,178,240,.22); color: #cfe2fb; }
.chip.ai { background: transparent; border: 1px dashed rgba(255,255,255,.3); color: var(--muted); }
.chip.E1, .chip.E2, .chip.approved { background: rgba(46,160,90,.2); color: #9fe0b8; }
.chip.E3, .chip.deferred, .chip.challenged { background: rgba(240,180,41,.18); color: #f6d58a; }
.chip.E4 { background: rgba(220,80,80,.2); color: #f3b0b0; }
.detail h3 { font-size: 17px; font-weight: 600; line-height: 1.3; margin: 4px 0 0; }
.detail p { font-size: 13px; line-height: 1.55; color: #c9d2de; margin: 10px 0 0; }
.sec { margin-top: 18px; }
.sec .lab { font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
.decision { border-left: 2px solid var(--blue2); padding: 2px 0 2px 12px; font-size: 13px; color: var(--text); line-height: 1.5; }
.mk { display: grid; grid-template-columns: 92px 1fr 52px; align-items: center; gap: 10px; font-size: 12.5px; padding: 4px 0; }
.mk .b { height: 6px; background: rgba(255,255,255,.07); border-radius: 3px; overflow: hidden; }
.mk .b i { display: block; height: 100%; background: var(--could); }
.mk .b i.Must { background: var(--blue2); } .mk .b i.Should { background: var(--should); }
.mk.cur { color: #fff; font-weight: 600; }
.mk .p { color: var(--muted); text-align: right; font-size: 11.5px; }
.opt { display: flex; justify-content: space-between; gap: 10px; font-size: 12.5px; padding: 5px 0; border-bottom: 1px solid var(--line); color: #c9d2de; }
.opt span:last-child { color: var(--muted); font-size: 11px; white-space: nowrap; }
.note { font-size: 11px; color: var(--muted); margin-top: 6px; line-height: 1.45; }
.back { cursor: pointer; color: var(--muted); font-size: 12px; } .back:hover { color: var(--text); }
.foot { padding: 12px 16px; border-top: 1px solid var(--line); display: flex; gap: 8px; }
.foot .btn { flex: 1; justify-content: center; border-radius: 8px; padding: 9px 12px; font-size: 13px; }

// 3D car view (D-039): Sketchfab viewer + our own hotspot overlay. Requirement text never goes to the viewer —
// only camera commands do; pins are DOM elements positioned with getWorldToScreenCoordinates.
const SF_SRC = "https://static.sketchfab.com/api/sketchfab-viewer-1.12.1.js";
const PRI = { Must: 0, Should: 1, Could: 2 };

function loadSketchfab() {
  if (window.__sfLoad) return window.__sfLoad;
  window.__sfLoad = new Promise((resolve, reject) => {
    if (window.Sketchfab) return resolve(window.Sketchfab);
    const s = document.createElement("script");
    s.src = SF_SRC; s.async = true;
    s.onload = () => resolve(window.Sketchfab);
    s.onerror = () => { window.__sfLoad = null; reject(new Error("Sketchfab viewer could not be loaded")); };
    document.head.appendChild(s);
  });
  return window.__sfLoad;
}

function el(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined && text !== null) e.textContent = String(text);
  return e;
}

// ---------------------------------------------------------------- car frame → world coordinates
function frame(model) {
  const [cx, cy] = model.center, L = model.half_len, W = model.half_wid, [z0, z1] = model.z;
  const F = model.fwd, R = model.right;
  const world = ([f, r, h]) => [cx + f * L * F[0] + r * W * R[0], cy + f * L * F[1] + r * W * R[1], z0 + h * (z1 - z0)];
  const dir = ([vf, vr, vh]) => {
    const v = [vf * F[0] + vr * R[0], vf * F[1] + vr * R[1], vh];
    const n = Math.hypot(...v) || 1;
    return v.map((x) => x / n);
  };
  return { world, dir, L };
}

function camFor(st, zoneId) {
  const fr = frame(st.data.model);
  if (!zoneId) {
    const target = fr.world([0, 0, 0.42]);
    const d = fr.dir([0.85, -0.95, 0.42]);
    return { eye: target.map((t, i) => t + d[i] * fr.L * 2.75), target };
  }
  const z = st.data.zones[zoneId];
  const target = fr.world(z.pos);
  const d = fr.dir(z.view);
  return { eye: target.map((t, i) => t + d[i] * fr.L * z.dist), target };
}

function fly(st, zoneId, secs) {
  if (!st.api || !st.ready) return;
  const c = camFor(st, zoneId);
  st.api.setCameraLookAt(c.eye, c.target, secs === undefined ? 1.4 : secs);
}

// ---------------------------------------------------------------- viewer
function initViewer(st) {
  const stage = st.stage;
  stage.classList.remove("ready");
  if (st.iframe) st.iframe.remove();
  const iframe = el("iframe");
  iframe.setAttribute("allow", "autoplay; fullscreen; xr-spatial-tracking");
  iframe.title = "3D model";
  stage.prepend(iframe);
  st.iframe = iframe; st.api = null; st.ready = false; st.uid = st.data.model.uid;
  const myUid = st.uid;
  loadSketchfab().then((Sketchfab) => {
    const client = new Sketchfab(iframe);
    client.init(myUid, {
      autostart: 1, preload: 1, dnt: 1, transparent: 0, camera: 0,
      ui_infos: 0, ui_controls: 0, ui_stop: 0, ui_inspector: 0, ui_watermark: 0, ui_watermark_link: 0,
      ui_ar: 0, ui_help: 0, ui_settings: 0, ui_vr: 0, ui_fullscreen: 0, ui_annotations: 0, ui_hint: 0,
      ui_theme: "dark",
      success: (api) => {
        if (st.uid !== myUid) return;
        st.api = api;
        api.start();
        api.addEventListener("viewerready", () => {
          if (st.uid !== myUid) return;
          st.ready = true;
          try { api.setBackground({ color: [0.07, 0.09, 0.12] }); } catch (e) { /* older viewer */ }
          fly(st, st.zone, 0);
          setTimeout(() => stage.classList.add("ready"), 250);
          api.addEventListener("camerachange", () => schedulePins(st));
          schedulePins(st);
        });
      },
      error: () => { st.loaderText.textContent = "3D model unavailable — check the internet connection"; },
    });
  }).catch((e) => { st.loaderText.textContent = e.message; });
}

// ---------------------------------------------------------------- pins
function zoneStats(st) {
  const out = {};
  for (const r of st.data.reqs) {
    const z = (out[r.zone] = out[r.zone] || { n: 0, top: "Could" });
    z.n += 1;
    if (PRI[r.priority] < PRI[z.top]) z.top = r.priority;
  }
  return out;
}

function buildPins(st) {
  st.pins.replaceChildren();
  st.pinEls = {};
  const stats = zoneStats(st);
  for (const [zid, z] of Object.entries(st.data.zones)) {
    if (!stats[zid]) continue;
    const p = el("div", `pin ${stats[zid].top}`);
    p.style.left = "-100px"; p.style.top = "-100px";
    p.appendChild(el("div", "dot", stats[zid].n));
    p.appendChild(el("div", "tag", z.label));
    p.onclick = () => selectZone(st, zid);
    st.pins.appendChild(p);
    st.pinEls[zid] = p;
  }
  schedulePins(st);
}

function schedulePins(st) {
  if (st.pinRaf) return;
  st.pinRaf = requestAnimationFrame(() => { st.pinRaf = null; updatePins(st); });
}

function updatePins(st) {
  if (!st.api || !st.ready) return;
  const fr = frame(st.data.model);
  const rect = st.iframe.getBoundingClientRect();
  st.api.getCameraLookAt((err, cam) => {
    if (err || !cam) return;
    const cd = cam.position.map((v, i) => v - cam.target[i]);
    const cn = Math.hypot(...cd) || 1;
    for (const [zid, p] of Object.entries(st.pinEls)) {
      const z = st.data.zones[zid];
      st.api.getWorldToScreenCoordinates(fr.world(z.pos), (e, res) => {
        if (e || !res) return;
        let xy = res.canvasCoord || res.glCoord;
        if (!xy) return;
        let [x, y] = xy;
        if (!res.canvasCoord) y = rect.height - y;   // glCoord origin is bottom-left
        const scale = res.canvasCoord && rect.width ? rect.width / (st.iframe.contentWindow ? rect.width : rect.width) : 1;
        p.style.left = `${x * scale}px`;
        p.style.top = `${y * scale}px`;
        const facing = fr.dir(z.view).reduce((s, v, i) => s + v * cd[i] / cn, 0);
        p.classList.toggle("behind", facing < -0.15);
        p.classList.toggle("dim", !!st.zone && st.zone !== zid);
        p.classList.toggle("sel", st.zone === zid);
      });
    }
  });
}

// ---------------------------------------------------------------- selection
function selectZone(st, zid) {
  st.zone = zid; st.req = null;
  stopTour(st);
  fly(st, zid);
  renderPanel(st); renderRail(st); schedulePins(st);
}

function selectReq(st, rid) {
  const r = st.data.reqs.find((x) => x.id === rid);
  if (!r) return;
  st.req = rid; st.zone = r.zone;
  stopTour(st);
  fly(st, r.zone);
  renderPanel(st); renderRail(st); schedulePins(st);
}

function overview(st) {
  st.zone = null; st.req = null;
  stopTour(st);
  fly(st, null);
  renderPanel(st); renderRail(st); schedulePins(st);
}

function stopTour(st) {
  if (st.tour) { clearInterval(st.tour); st.tour = null; }
  if (st.tourBtn) st.tourBtn.classList.remove("on");
}

function startTour(st) {
  if (st.tour) { stopTour(st); return; }
  const stats = zoneStats(st);
  const order = Object.keys(st.data.zones).filter((z) => stats[z]);
  if (!order.length) return;
  let i = Math.max(0, order.indexOf(st.zone) + 1) % order.length;
  const step = () => {
    st.zone = order[i % order.length]; st.req = null; i += 1;
    fly(st, st.zone, 1.8);
    renderPanel(st); renderRail(st); schedulePins(st);
  };
  step();
  st.tour = setInterval(step, 5000);
  st.tourBtn.classList.add("on");
}

// ---------------------------------------------------------------- panel
function itemRow(st, r) {
  const it = el("div", `item${st.req === r.id ? " sel" : ""}`);
  it.appendChild(el("div", `pd ${r.priority}`));
  const mid = el("div");
  mid.appendChild(el("div", "t", r.title));
  mid.appendChild(el("div", "m", `${r.priority}${r.ai ? " · AI suggests" : ""} · ${r.evidence_label} · ${r.status_label}`));
  it.appendChild(mid);
  const sc = el("div", "sc", Math.round(r.score));
  const bar = el("div", "bar"); const fill = el("i"); fill.style.width = `${Math.max(4, Math.min(100, r.score))}%`;
  bar.appendChild(fill); sc.appendChild(bar);
  it.appendChild(sc);
  it.onclick = () => selectReq(st, r.id);
  return it;
}

function renderList(st, body) {
  const reqs = st.data.reqs.filter((r) => !st.zone || r.zone === st.zone);
  if (!reqs.length) { body.appendChild(el("div", "empty", "No recommended improvements here for this market.")); return; }
  const zones = st.zone ? [st.zone] : Object.keys(st.data.zones);
  for (const zid of zones) {
    const rs = reqs.filter((r) => r.zone === zid);
    if (!rs.length) continue;
    const g = el("div", "group");
    if (!st.zone) {
      const gh = el("div", "gh");
      gh.appendChild(el("span", null, st.data.zones[zid].label));
      gh.appendChild(el("span", null, rs.length));
      gh.onclick = () => selectZone(st, zid);
      g.appendChild(gh);
    }
    rs.forEach((r) => g.appendChild(itemRow(st, r)));
    body.appendChild(g);
  }
  if (st.zone) renderOptions(st, body, st.zone);
}

function renderOptions(st, body, zid) {
  const opts = (st.data.options || {})[zid] || [];
  const sec = el("div", "sec");
  sec.appendChild(el("div", "lab", "Today's car in this area"));
  if (!opts.length) sec.appendChild(el("div", "note", "No matching equipment on the current price list."));
  for (const o of opts) {
    const row = el("div", "opt");
    row.appendChild(el("span", null, o.name));
    row.appendChild(el("span", null, o.avail));
    sec.appendChild(row);
  }
  if (st.data.option_note) sec.appendChild(el("div", "note", st.data.option_note));
  body.appendChild(sec);
}

function renderDetail(st, body, r) {
  const d = el("div", "detail");
  const back = el("div", "back", `← ${st.data.zones[r.zone].label}`);
  back.onclick = () => selectZone(st, r.zone);
  d.appendChild(back);
  d.appendChild(el("h3", null, r.title));
  const chips = el("div", "chips");
  chips.appendChild(el("span", `chip ${r.priority}`, r.priority));
  if (r.ai) chips.appendChild(el("span", "chip ai", "AI suggests — PM to confirm"));
  chips.appendChild(el("span", `chip ${r.evidence}`, r.evidence_label));
  chips.appendChild(el("span", `chip ${r.status}`, r.status_label));
  if (r.kano) chips.appendChild(el("span", "chip", r.kano));
  if (r.horizon) chips.appendChild(el("span", "chip", r.horizon));
  d.appendChild(chips);
  if (r.description) d.appendChild(el("p", null, r.description));
  if (r.decision) {
    const s = el("div", "sec");
    s.appendChild(el("div", "lab", "Product decision it asks for"));
    s.appendChild(el("div", "decision", r.decision));
    d.appendChild(s);
  }
  if (r.markets && r.markets.length) {
    const s = el("div", "sec");
    s.appendChild(el("div", "lab", `Score by market · ${st.data.car}`));
    for (const m of r.markets) {
      const row = el("div", `mk${m.cur ? " cur" : ""}`);
      row.appendChild(el("span", null, m.label));
      const b = el("div", "b"); const i = el("i", m.priority); i.style.width = `${Math.max(3, Math.min(100, m.score))}%`;
      b.appendChild(i); row.appendChild(b);
      row.appendChild(el("span", "p", `${m.priority} ${Math.round(m.score)}`));
      s.appendChild(row);
    }
    d.appendChild(s);
  }
  body.appendChild(d);
  renderOptions(st, body, r.zone);
}

function renderPanel(st) {
  const D = st.data;
  st.panel.replaceChildren();
  const head = el("div", "head");
  const r = st.req && D.reqs.find((x) => x.id === st.req);
  head.appendChild(el("div", "eyebrow", r ? r.id : st.zone ? "Zone" : "Recommended improvements"));
  const t = el("div", "title");
  t.appendChild(el("span", null, r ? D.zones[r.zone].label : st.zone ? D.zones[st.zone].label : `${D.reqs.length} for the successor`));
  if (st.zone || r) {
    const all = el("button", "btn", "Whole car");
    all.onclick = () => overview(st);
    t.appendChild(all);
  }
  head.appendChild(t);
  st.panel.appendChild(head);
  const body = el("div", "body");
  if (r) renderDetail(st, body, r); else renderList(st, body);
  st.panel.appendChild(body);
  if (r) {
    const foot = el("div", "foot");
    const open = el("button", "btn primary", "Review & decide →");
    open.onclick = () => st.setTriggerValue("open_review", r.id);
    const det = el("button", "btn", "Full trace");
    det.onclick = () => st.setTriggerValue("open_detail", r.id);
    foot.appendChild(det); foot.appendChild(open);
    st.panel.appendChild(foot);
  }
}

function renderRail(st) {
  st.rail.replaceChildren();
  const stats = zoneStats(st);
  const all = el("button", `btn${!st.zone ? " on" : ""}`, "Whole car");
  all.onclick = () => overview(st);
  st.rail.appendChild(all);
  for (const [zid, z] of Object.entries(st.data.zones)) {
    if (!stats[zid]) continue;
    const b = el("button", `btn${st.zone === zid ? " on" : ""}`);
    b.appendChild(el("span", null, z.label));
    b.appendChild(el("span", "n", stats[zid].n));
    b.onclick = () => selectZone(st, zid);
    st.rail.appendChild(b);
  }
}

function renderHud(st) {
  const D = st.data;
  st.hudTitle.textContent = D.car;
  st.hudSub.replaceChildren();
  const must = D.reqs.filter((r) => r.priority === "Must").length;
  st.hudSub.append(D.market, " · ", el("b", null, D.reqs.length), " improvements · ", el("b", null, must), " Must");
  st.cfg.style.display = D.configurator ? "" : "none";
  if (D.configurator) st.cfg.href = D.configurator;
  const m = D.model;
  st.credit.replaceChildren();
  const a = el("a", null, `“${m.name}” by ${m.author}`);
  a.href = `https://sketchfab.com/3d-models/${m.uid}`; a.target = "_blank"; a.rel = "noopener";
  st.credit.append("3D model ", a, ` · ${m.license} · Sketchfab`);
  if (m.stand_in) st.credit.append(el("div", null, m.stand_in));
}

// ---------------------------------------------------------------- mount
export default function (component) {
  const { data, parentElement, setTriggerValue } = component;
  if (!data) return;
  const host = parentElement.host || parentElement;
  let st = host.__car3d;
  if (!st) {
    st = host.__car3d = { zone: null, req: null };
    const root = el("div", "studio");
    st.stage = el("div", "stage");
    const loader = el("div", "loader");
    const lw = el("div");
    st.loaderText = el("div", null, "Loading 3D model");
    lw.appendChild(st.loaderText);
    const bar = el("div", "bar"); bar.appendChild(el("i")); lw.appendChild(bar);
    loader.appendChild(lw);
    st.stage.appendChild(loader);
    const hud = el("div", "hud");
    const left = el("div");
    st.hudTitle = el("h2"); st.hudSub = el("div", "sub");
    left.append(st.hudTitle, st.hudSub);
    const tools = el("div", "tools");
    st.tourBtn = el("button", "btn", "▶ Tour");
    st.tourBtn.onclick = () => startTour(st);
    st.cfg = el("a", "btn", "BMW configurator ↗");
    st.cfg.target = "_blank"; st.cfg.rel = "noopener";
    tools.append(st.tourBtn, st.cfg);
    hud.append(left, tools);
    st.pins = el("div", "pins");
    st.rail = el("div", "rail");
    st.credit = el("div", "credit");
    st.stage.append(hud, st.pins, st.credit, st.rail);
    st.panel = el("div", "panel");
    root.append(st.stage, st.panel);
    parentElement.appendChild(root);
    st.ro = new ResizeObserver(() => schedulePins(st));
    st.ro.observe(st.stage);
  }
  st.setTriggerValue = setTriggerValue;
  const changedView = !st.data || st.data.key !== data.key;
  st.data = data;
  if (changedView) { st.zone = data.focus_zone || null; st.req = data.focus_req || null; stopTour(st); }
  if (st.req && !data.reqs.some((r) => r.id === st.req)) st.req = null;
  if (!st.api || st.uid !== data.model.uid) initViewer(st);
  else if (changedView) fly(st, st.zone);
  renderHud(st); buildPins(st); renderRail(st); renderPanel(st);
}

