import { useEffect, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "motion/react";
import { X } from "lucide-react";

/** Right-hand sheet for detail that shouldn't cost the PM their place (evidence, findings, sources). */
export function Drawer({ open, onClose, title, sub, children, width }: { open: boolean; onClose: () => void; title: ReactNode; sub?: ReactNode; children: ReactNode; width?: number }) {
  useEffect(() => {
    if (!open) return;
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, onClose]);
  return createPortal(
    <AnimatePresence>
      {open && (
        <>
          <motion.div className="drawer-scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={onClose} />
          <motion.aside
            className="drawer"
            role="dialog"
            aria-modal="true"
            style={width ? { width: `min(${width}px, calc(100vw - 20px))` } : undefined}
            initial={{ x: 40, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: 30, opacity: 0, transition: { duration: 0.16 } }}
            transition={{ duration: 0.34, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="drawer-head">
              <div className="grow">
                <div className="t-title">{title}</div>
                {sub && <div className="muted t-small" style={{ marginTop: 4 }}>{sub}</div>}
              </div>
              <button className="btn btn-ghost btn-icon btn-sm" onClick={onClose} aria-label="Close">
                <X />
              </button>
            </div>
            <div className="drawer-body">{children}</div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>,
    document.body,
  );
}

// ⌘K: jump to any requirement, car · market, or screen from anywhere — the fastest path in a live demo.
import { useEffect } from "react";
import { createPortal } from "react-dom";
import { useNavigate } from "react-router-dom";
import { Command } from "cmdk";
import { useQuery } from "@tanstack/react-query";
import { Car, FileText, Globe2, Play } from "lucide-react";
import { api } from "@/lib/api";
import type { RequirementSummary } from "@/lib/types";
import { CAR, MARKET } from "@/lib/labels";
import { NAV } from "./Shell";

const CAR_MARKETS: [string, string[]][] = [
  ["F70", ["EU", "RoW"]],
  ["G60", ["US", "EU", "RoW"]],
  ["G68", ["CN"]],
  ["G70", ["US", "EU", "CN", "RoW"]],
];

export function CommandPalette({ open, setOpen }: { open: boolean; setOpen: (v: boolean) => void }) {
  const nav = useNavigate();
  const reqs = useQuery({
    queryKey: ["requirements", "palette"],
    queryFn: () => api.get<RequirementSummary[]>("/api/requirements?include_rejected=true"),
    enabled: open,
  });

  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        setOpen(!open);
      }
      if (e.key === "Escape" && open) setOpen(false);
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, setOpen]);

  if (!open) return null;
  const go = (to: string) => {
    setOpen(false);
    nav(to);
  };
  return createPortal(
    <div className="cmdk-scrim" onMouseDown={(e) => e.target === e.currentTarget && setOpen(false)}>
      <Command className="cmdk-box" label="Search and commands" loop>
        <Command.Input autoFocus placeholder="Search requirements, cars, markets, screens…" />
        <Command.List>
          <Command.Empty>No match.</Command.Empty>
          <Command.Group heading="Go to">
            {NAV.map((n) => (
              <Command.Item key={n.to} value={`screen ${n.label}`} onSelect={() => go(n.to)}>
                <n.icon /> {n.label}
                <span className="cmdk-hint">{n.key}</span>
              </Command.Item>
            ))}
            <Command.Item value="start deciding queue review" onSelect={() => go("/decide")}>
              <Play /> Start deciding
            </Command.Item>
          </Command.Group>
          <Command.Group heading="Cars">
            {CAR_MARKETS.flatMap(([v, ms]) =>
              ms.map((m) => (
                <Command.Item key={`${v}${m}`} value={`car ${CAR[v]} ${MARKET[m]} ${v} ${m}`} onSelect={() => go(`/cars/${v}?market=${m}`)}>
                  <Car /> {CAR[v]} · {MARKET[m]}
                </Command.Item>
              )),
            )}
          </Command.Group>
          <Command.Group heading="Markets">
            {Object.entries(MARKET).map(([m, l]) => (
              <Command.Item key={m} value={`market ${l} ${m}`} onSelect={() => go(`/markets/${m}`)}>
                <Globe2 /> {l}
              </Command.Item>
            ))}
          </Command.Group>
          <Command.Group heading="Requirements">
            {(reqs.data ?? []).map((r) => (
              <Command.Item key={r.id} value={`${r.id} ${r.title} ${r.category}`} onSelect={() => go(`/requirements/${r.id}`)}>
                <FileText />
                <span className="id">{r.id}</span>
                <span className="ellipsis">{r.title}</span>
              </Command.Item>
            ))}
          </Command.Group>
        </Command.List>
      </Command>
    </div>,
    document.body,
  );
}

